&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt;Prix&lt;/b&gt; 20 po ; &lt;b&gt;Poids&lt;/b&gt; 1,5 kg ; &lt;b&gt;Groupes&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Groupe-Darmes.html#Armesdejet&quot; title=&quot;Les groupes d&amp;#39;arme du guerrier&quot;&gt;armes de jet&lt;/a&gt;  
&lt;b&gt;D&#233;g&#226;ts&lt;/b&gt; 1d6 (P), 1d8 (M) ; &lt;b&gt;Critique&lt;/b&gt; &#215;3 ; &lt;b&gt;Port&#233;e&lt;/b&gt; 24 m (16 c) ; &lt;b&gt;Type&lt;/b&gt; C ; &lt;b&gt;Sp&#233;cial&lt;/b&gt; —  
&lt;span class=&quot;Cat&#233;gorie&quot;&gt;&lt;b&gt;Cat&#233;gorie&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes.html#TABEXOTIQUES&quot; title=&quot;Tableau r&#233;capitulatif des armes&quot;&gt;Armes exotiques&lt;/a&gt; ; &lt;b&gt;Maniement&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armeadistance.html&quot; title=&quot;arme &#224; distance&quot;&gt;arme &#224; distance&lt;/a&gt;&lt;/span&gt;
&lt;hr&gt;
&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Dans le &lt;u&gt;Manuel des joueurs&lt;/u&gt;, cet objet est aussi appel&#233; &quot;b&#226;ton de jet halfelin&quot;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
